-- Functions
CREATE OR REPLACE FUNCTION public.legal_activate_firm_offer_pack(_offer_id uuid, _firm_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o jsonb; pid uuid; begin
 perform 1 from legal_firms where id=_firm_id for update;
 if not found then raise exception 'Firm not found'; end if;
 select snapshot into o from legal_firm_offers where id=_offer_id for update;
 if o is null or o->>'proposal'<>'sent' or o->>'signature'<>'executed' or o->'payments'->0->>'status'<>'paid' or not (o->>'onboardingComplete')::boolean then raise exception 'Activation requirements incomplete'; end if;
 select id into pid from legal_firm_packs where offer_id=_offer_id;
 if found then return pid; end if;
 if exists(select 1 from legal_firm_packs where firm_id=_firm_id and status='active') then raise exception 'Existing active packs require an explicit migration decision'; end if;
 insert into legal_firm_packs(firm_id,pack_size,price_per_show,price_per_show_cents,offer_id) values(_firm_id,10,((o->'draft'->>'priceCents')::numeric/100)::integer,(o->'draft'->>'priceCents')::bigint,_offer_id) returning id into pid;
 return pid;
end $function$;
CREATE OR REPLACE FUNCTION public.legal_bridge_appointment_reminder()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.kind IN ('3d','1d','24h') AND NEW.send_at IS NOT NULL THEN
    INSERT INTO legal_appointment_reminder_jobs(appointment_id,booking_version,kind,due_at,state,sent_at)
    SELECT NEW.appointment_id,booking_version,CASE WHEN NEW.kind='24h' THEN '1d' ELSE NEW.kind END,NEW.send_at,
      CASE WHEN NEW.sent_at IS NULL THEN 'pending' ELSE 'sent' END,NEW.sent_at
    FROM legal_appointment_attendance WHERE appointment_id=NEW.appointment_id ON CONFLICT DO NOTHING;
    IF NEW.sent_at IS NOT NULL THEN
      UPDATE legal_appointment_reminder_jobs SET state='sent',sent_at=NEW.sent_at
        WHERE appointment_id=NEW.appointment_id AND kind=CASE WHEN NEW.kind='24h' THEN '1d' ELSE NEW.kind END
        AND due_at=NEW.send_at AND state='pending';
    END IF;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_can_access_portal_page(p_page text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(SELECT 1 FROM public.legal_sales_reps r WHERE r.user_id = auth.uid() AND r.is_active
    AND (p_page = ANY(public.legal_staff_portal_pages(r.id))
      OR (r.role = 'admin' AND p_page IN ('/settings','/ad-briefing'))));
$function$;
CREATE OR REPLACE FUNCTION public.legal_can_manage_firm_pipeline()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.legal_can_access_portal_page('/firms') AND EXISTS(
    SELECT 1 FROM public.legal_sales_reps r WHERE r.user_id=auth.uid() AND r.is_active
      AND (r.role='admin' OR r.can_manage_firm_pipeline));
$function$;
CREATE OR REPLACE FUNCTION public.legal_can_view_team_clients()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.legal_sales_reps r
    WHERE r.user_id = auth.uid() AND r.is_active
      AND r.role IN ('admin', 'rep') AND r.can_view_team_clients
  );
$function$;
CREATE OR REPLACE FUNCTION public.legal_capture_appointment_office()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE office public.legal_firm_locations; active_count int; choosing boolean;
BEGIN
 choosing:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN
   choosing:=NEW.location_id IS DISTINCT FROM OLD.location_id OR NEW.firm_id IS DISTINCT FROM OLD.firm_id;
   -- Updates to dates/outcomes keep the exact directions supplied at booking.
   IF NOT choosing THEN
     NEW.location_revision:=OLD.location_revision;
     NEW.location_name:=OLD.location_name; NEW.location_address:=OLD.location_address;
     NEW.location_parking_info:=OLD.location_parking_info; NEW.location_nearby_landmarks:=OLD.location_nearby_landmarks;
     IF NEW.consult_mode IS NOT DISTINCT FROM OLD.consult_mode THEN RETURN NEW; END IF;
   END IF;
 END IF;
 IF NEW.firm_id IS NULL THEN
   IF NEW.location_id IS NOT NULL THEN RAISE EXCEPTION 'Choose an office at the selected firm'; END IF;
   NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.location_revision+1 END;
   NEW.location_name:=NULL; NEW.location_address:=NULL; NEW.location_parking_info:=NULL; NEW.location_nearby_landmarks:=NULL;
   RETURN NEW;
 END IF;
 -- Use the same firm lock as booking capacity and calendar checks.
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.firm_id::text,0));
 IF NEW.location_id IS NULL AND coalesce(NEW.consult_mode,'in_person')<>'zoom' THEN
   SELECT count(*) INTO active_count FROM public.legal_firm_locations WHERE firm_id=NEW.firm_id AND is_active;
   IF active_count<>1 THEN RAISE EXCEPTION 'Choose an office for this in-person appointment'; END IF;
   SELECT id INTO NEW.location_id FROM public.legal_firm_locations WHERE firm_id=NEW.firm_id AND is_active;
   choosing:=true;
 END IF;
 IF NEW.location_id IS NOT NULL THEN
   SELECT * INTO office FROM public.legal_firm_locations WHERE id=NEW.location_id AND firm_id=NEW.firm_id FOR SHARE;
   IF NOT FOUND OR (choosing AND NOT office.is_active) THEN RAISE EXCEPTION 'Choose an active office at the selected firm'; END IF;
   IF choosing THEN
     NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 1 ELSE OLD.location_revision+1 END;
     NEW.location_name:=office.name;
     NEW.location_address:=nullif(concat_ws(', ',nullif(trim(office.address),''),nullif(trim(office.city),''),nullif(trim(office.state),'')),'');
     NEW.location_parking_info:=office.parking_info; NEW.location_nearby_landmarks:=office.nearby_landmarks;
   END IF;
 ELSE
   NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.location_revision+1 END;
   NEW.location_name:=NULL; NEW.location_address:=NULL; NEW.location_parking_info:=NULL; NEW.location_nearby_landmarks:=NULL;
 END IF;
 RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_capture_legal_booking_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.booking_rep_id IS DISTINCT FROM OLD.booking_rep_id THEN RAISE EXCEPTION 'Booking ownership is immutable'; END IF;
  RETURN NEW;
 END IF;
 IF auth.uid() IS NOT NULL THEN
  SELECT id INTO NEW.booking_rep_id FROM legal_sales_reps WHERE user_id=auth.uid() AND is_active LIMIT 1;
 END IF;
 RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_claim_appointment_reminder(p_id uuid, p_from text, p_to text, p_settings_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j legal_appointment_reminder_jobs; s legal_appointment_attendance; a legal_firm_appointments; cfg legal_firm_reminder_settings; start_at timestamptz; last_contact timestamptz;
BEGIN
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE id=p_id;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO a FROM legal_firm_appointments WHERE id=j.appointment_id FOR UPDATE;
  SELECT * INTO s FROM legal_appointment_attendance WHERE appointment_id=j.appointment_id FOR UPDATE;
  SELECT * INTO cfg FROM legal_firm_reminder_settings WHERE firm_id=a.firm_id FOR SHARE;
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE id=p_id FOR UPDATE;
  IF j.state<>'pending' OR j.due_at>now() OR j.booking_version<>s.booking_version OR a.status<>'booked' OR a.outcome IS NOT NULL OR cfg.mode='off' OR cfg.firm_id IS NULL THEN RETURN false; END IF;
  BEGIN start_at := (a.appointment_date::text || ' ' || a.appointment_time)::timestamp AT TIME ZONE cfg.timezone;
  EXCEPTION WHEN OTHERS THEN RETURN false; END;
  IF start_at IS NULL OR start_at<=now() THEN RETURN false; END IF;
  IF p_settings_updated_at IS NOT NULL AND p_settings_updated_at<>cfg.updated_at THEN RETURN false; END IF;
  IF j.kind<>'ack' AND s.booking_changed_at>now()-interval '10 minutes' THEN RETURN false; END IF;
  IF j.kind IN ('request','followup') AND cfg.confirmation_enabled_at>now()-interval '10 minutes' THEN RETURN false; END IF;
  IF j.kind IN ('request','followup','call') AND (cfg.mode<>'confirmation' OR s.status='confirmed') THEN RETURN false; END IF;
  IF j.kind IN ('request','followup') AND s.status IN ('needs_call','review') THEN RETURN false; END IF;
  IF j.kind='ack' AND s.status<>'confirmed' THEN RETURN false; END IF;
  IF j.kind<>'call' AND (p_to IS NULL OR EXISTS(SELECT 1 FROM legal_appointment_sms_opt_outs WHERE phone=p_to)) THEN RETURN false; END IF;
  IF j.kind IN ('request','followup','3d','1d') OR (j.kind='call' AND s.status='awaiting') THEN
    SELECT max(COALESCE(sent_at,claimed_at)) INTO last_contact FROM legal_appointment_reminder_jobs
    WHERE appointment_id=j.appointment_id AND kind<>'call' AND state IN ('sending','sent','uncertain');
    IF last_contact>now()-interval '2 hours' THEN
      UPDATE legal_appointment_reminder_jobs SET due_at=last_contact+interval '2 hours' WHERE id=j.id;
      RETURN false;
    END IF;
  END IF;
  IF j.kind='call' AND s.status='awaiting' AND EXISTS(
    SELECT 1 FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='followup' AND state='pending'
  ) THEN
    UPDATE legal_appointment_reminder_jobs SET due_at=GREATEST(now()+interval '15 minutes',
      (SELECT due_at+interval '2 hours' FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='followup')) WHERE id=j.id;
    RETURN false;
  END IF;
  IF j.kind='followup' AND NOT EXISTS(SELECT 1 FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='request' AND state='sent') THEN RETURN false; END IF;
  UPDATE legal_appointment_reminder_jobs SET state='sending',claimed_at=now(),from_phone=p_from,to_phone=p_to WHERE id=j.id;
  IF j.kind='request' AND s.status='unrequested' THEN UPDATE legal_appointment_attendance SET status='awaiting' WHERE appointment_id=j.appointment_id; END IF;
  IF j.kind='call' THEN UPDATE legal_appointment_attendance SET status=CASE WHEN status='review' THEN 'review' ELSE 'needs_call' END,reason=COALESCE(reason,'Attendance has not been confirmed') WHERE appointment_id=j.appointment_id; END IF;
  RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION public.legal_claim_call_hook(p_call uuid, p_hash text, p_version text, p_model text, p_user uuid, p_regenerate boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE token uuid:=gen_random_uuid(); existing legal_call_hook_insights;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 IF p_hash !~ '^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM legal_call_records WHERE id=p_call AND lead_id IS NOT NULL) THEN RAISE EXCEPTION 'Invalid call'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('call_hook:'||p_call::text,0));
 SELECT * INTO existing FROM legal_call_hook_insights WHERE call_id=p_call FOR UPDATE;
 IF FOUND THEN
   IF existing.status='processing' AND existing.lease_until>now() THEN RETURN NULL; END IF;
   IF existing.source_hash=p_hash AND existing.status IN ('ready','unknown','excluded') AND NOT p_regenerate THEN RETURN NULL; END IF;
 END IF;
 INSERT INTO legal_call_hook_insights(call_id,source_hash,prompt_version,model,status,attempts,generation_token,lease_until,requested_by,reason)
 VALUES(p_call,p_hash,p_version,p_model,'processing',1,token,now()+interval '10 minutes',p_user,'Reviewing client conversation')
 ON CONFLICT(call_id) DO UPDATE SET source_hash=excluded.source_hash,prompt_version=excluded.prompt_version,
 model=excluded.model,status='processing',
 attempts=CASE WHEN legal_call_hook_insights.source_hash=p_hash THEN legal_call_hook_insights.attempts+1 ELSE 1 END,
 generation_token=token,lease_until=excluded.lease_until,requested_by=p_user,reason=excluded.reason,updated_at=now();
 RETURN token;
END $function$;

RESET check_function_bodies;
